import java.util.*;

public class Main {
    int getSum(int a, int b) {
        if (b >= 0) {
            for (int i = 0; i < b; i++) a++;                          // increment one at a time, b times
        } else {
            for (int i = 0; i < -b; i++) a--;                          // decrement one at a time for a negative b
        }
        return a;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.getSum(1, 2));
    }
}

