def get_sum(a, b):
    if b >= 0:
        for _ in range(b):
            a += 1                                              # increment one at a time, b times
    else:
        for _ in range(-b):
            a -= 1                                              # decrement one at a time for a negative b
    return a


if __name__ == "__main__":
    print(get_sum(1, 2))

