import java.util.*;

public class Main {
    int getSum(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;                                    // bits that need to carry into the next position
            a = a ^ b;                                                     // sum of this round, ignoring carrying
            b = carry;
        }
        return a;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.getSum(2, 3));
    }
}

