def get_sum(a, b):
    mask = 0xFFFFFFFF                                         # keeps values within 32 bit range
    while b != 0:
        carry = (a & b) << 1                                     # bits that need to carry into the next position
        a = (a ^ b) & mask                                         # sum of this round, ignoring carrying
        b = carry & mask
    return a if a <= 0x7FFFFFFF else ~(a ^ mask)                  # convert back to a signed result if needed


if __name__ == "__main__":
    print(get_sum(2, 3))

